let saved; try {saved=JSON.parse(localStorage.getItem(KEY)||'null')} catch {}
let records=Array.isArray(saved?.records)?saved.records:[], wrong=new Set((Array.isArray(saved?.wrong)?saved.wrong:[]).map(id=>QUESTION_ID_MIGRATIONS[id]||id).filter(id=>QUESTIONS.some(q=>q.id===id)));
let tab='practice', category='전체', type='all', count=10, session=null;
