function badge(){$('#wrong-badge').textContent=wrong.size}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function pool(){return QUESTIONS.filter(q=>(category==='전체'||q.category===category)&&(type==='all'||q.type===type))}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function nav(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));badge()}
function setTab(t){if(session&&!session.done){toast('진행 중인 문제를 마치거나 학습을 종료해주세요.');return}tab=t;nav();render()}
