function renderHome(){session=null;const today=records.filter(r=>r.day===dateKey());const n=today.reduce((a,r)=>a+r.total,0), correct=today.reduce((a,r)=>a+r.correct,0),graded=today.reduce((a,r)=>a+gradedCount(r),0);const available=pool().length;
$('#main').innerHTML=`<section class="intro"><div><div class="eyebrow">정보처리기사 · 실기 전용</div><h1>정보처리기사 실기 연습</h1><p>과목과 유형을 고르고 문제를 풀어보세요.<br>정답과 해설을 확인하고, 틀린 문제는 다시 연습할 수 있어요.</p></div><div class="intro-art" aria-hidden="true"><div class="paper"><div></div><div></div><div></div><span>✓</span></div></div></section><div class="grid"><section class="card"><div class="card-title"><span class="tiny-icon" aria-hidden="true">☷</span><h2>어떤 문제를 풀어볼까요?</h2></div><div class="field"><div class="field-label">학습 범위<small>한 과목에 집중해도 좋아요</small></div><div class="pills">${categories.map(c=>`<button class="pill ${c===category?'selected':''}" data-cat="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div></div><div class="field"><div class="field-label">문제 유형<small>보기 없이 직접 답안을 작성해요</small></div><div class="segmented">${[['all','전체 유형'],['short','용어 단답형'],['output','출력·계산'],['blank','빈칸 채우기'],['sql','SQL 작성'],['essay','서술형']].map(([t,l])=>`<button class="segment ${type===t?'selected':''}" data-type="${t}" aria-pressed="${type===t}">${l}</button>`).join('')}</div></div><div class="setting-row"><div class="field"><label class="field-label" for="count">문제 수</label><select id="count" class="select">${[5,10,20].map(n=>`<option value="${n}" ${count===n?'selected':''}>${n}문제</option>`).join('')}</select></div><div class="field"><div class="field-label">출제 방식</div><div class="select" style="background:#fafafa;color:#737373">무작위 · 중복 없이</div></div></div><div class="start-info"><span>준비된 문제 ${available}개</span><span>약 ${Math.min(count,available)}분 학습</span></div><button id="start" class="btn full start-btn" ${available?'':'disabled'}><span>${available?'문제 풀기 시작':'해당 유형의 문제가 없어요'}</span><span aria-hidden="true">→</span></button><p class="footnote">${available&&available<count?`선택 범위에 있는 ${available}문제 모두 출제합니다.`:'정답 확인 후, 해설까지 천천히 읽어보세요.'}</p></section><aside class="side"><section class="card"><h2>오늘의 학습</h2><div class="stats"><div><div class="stat-label">완료한 문제</div><div class="stat-number">${n}<small>문제</small></div></div><div><div class="stat-label">정답률</div><div class="stat-number">${graded?Math.round(correct/graded*100):0}<small>%</small></div></div></div><div class="rule"></div><div class="side-bottom"><span>다시 볼 오답</span><span>${wrong.size}문제</span></div></section><section class="card note-card"><span class="mini-label">STUDY NOTE</span><h3>정답보다 중요한 건<br>왜 그런지 이해하는 것.</h3><p>틀린 문제는 오답노트에 모아둘게요.<br>다시 풀고, 내 것으로 만들어 보세요.</p><button class="inline-link" id="go-wrong">오답노트 보기 →</button></section><div class="source-teaser"><button class="inline-link" id="home-focus">디자인 패턴·아키텍처 집중 연습 →</button><br><br><strong>내 자료로 만드는 공부 습관</strong><br>첨부한 요약·계산·키워드 자료의 핵심 개념을<br>${QUESTIONS.length}개의 연습 문제로 구성했어요.</div></aside></div><div class="bottom-note"><span class="dot"></span>학습 기록은 이 브라우저에 저장됩니다. 서술형은 답안을 비교하며, 정답률은 자동 채점 문제 기준입니다.</div>`;
document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;renderHome()});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;renderHome()});$('#count').onchange=e=>{count=Number(e.target.value);renderHome()};$('#start').onclick=()=>start(pool(),category+' · '+typeName(type),count);$('#go-wrong').onclick=()=>setTab('wrong');$('#home-focus').onclick=()=>setTab('focus')}
function focusPool(){return QUESTIONS.filter(q=>(focusTopic==='core'?!!q.examEvidence:q.topic===focusTopic)&&(focusConcept==='all'||conceptKey(q)===focusConcept)&&(focusExercise==='all'||(focusTopic==='core'?(q.type==='blank'?'short':q.type)===focusExercise:q.exercise===focusExercise))&&(focusGroup==='all'||FOCUS_CONCEPTS.find(c=>c.id===q.concept)?.group===focusGroup))}
function selectQuestions(items,n,diverse=false){
 const evidenceRank=q=>tab==='focus'&&focusTopic==='core'?(q.examEvidence?.dates.length||0):0;
 const ranked = list => shuffle(list).sort((a,b)=>(attempts[a.id]||0)-(attempts[b.id]||0)||evidenceRank(b)-evidenceRank(a));
 if(!diverse)return ranked(items).slice(0,n);
 const groups=new Map();for(const q of items){const key=conceptKey(q);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(q);}
 const choices=shuffle([...groups.values()]).map(list=>({q:ranked(list)[0],total:list.reduce((sum,q)=>sum+(attempts[q.id]||0),0)}));
 choices.sort((a,b)=>a.total-b.total||(attempts[a.q.id]||0)-(attempts[b.q.id]||0)||evidenceRank(b.q)-evidenceRank(a.q));
 return choices.slice(0,n).map(x=>x.q);
}
function renderFocus(){session=null;const items=focusPool(),capacity=sessionCapacity(items),seen=items.filter(q=>attempts[q.id]).length,concepts=FOCUS_CONCEPTS.filter(c=>c.topic===focusTopic&&(focusGroup==='all'||c.group===focusGroup)),missed=items.filter(q=>wrong.has(q.id));
const selected=FOCUS_CONCEPTS.find(c=>c.id===focusConcept);const label='집중 연습 · '+focusTopicName(focusTopic)+(selected?' · '+selected.name:'');
$('#main').innerHTML=`<section class="intro"><div><div class="eyebrow">헷갈리는 개념만, 따로 연습</div><h1>기출 핵심부터, 중복 없이.</h1><p>실기 출제 이력을 확인한 개념과 보충 개념을 구분했어요.<br>같은 세트에서는 개념이 겹치지 않고, 덜 푼 문제를 먼저 출제합니다.</p></div></section><div class="grid"><section class="card"><div class="card-title"><h2>집중할 범위를 고르세요</h2></div><div class="field"><div class="field-label">학습 주제</div><div class="pills">${[['core','실기 기출 핵심'],['pattern','디자인 패턴 · 전체'],['architecture','아키텍처 · 보충']].map(([t,l])=>`<button class="pill ${focusTopic===t?'selected':''}" data-focus-topic="${t}" aria-pressed="${focusTopic===t}">${l}</button>`).join('')}</div></div>${focusTopic==='pattern'?`<div class="field"><div class="field-label">GoF 분류</div><div class="pills">${['all','생성','구조','행위'].map(g=>`<button class="pill ${focusGroup===g?'selected':''}" data-focus-group="${g}" aria-pressed="${focusGroup===g}">${g==='all'?'모든 분류':g+' 패턴'}</button>`).join('')}</div></div>`:''}<div class="field"><label class="field-label" for="focus-concept">특정 개념만 연습</label><select id="focus-concept" class="select"><option value="all">선택 범위 전체 · ${concepts.length}종</option>${concepts.map(c=>`<option value="${c.id}" ${focusConcept===c.id?'selected':''}>${esc(c.name)}${c.english?` (${esc(c.english)})`:""}</option>`).join('')}</select></div><div class="setting-row"><div class="field"><label class="field-label" for="focus-exercise">연습 방식</label><select id="focus-exercise" class="select">${(focusTopic==='core'?[['all','모든 실기 유형'],['short','핵심 용어·빈칸'],['output','출력·계산'],['sql','SQL 작성']]:[['all','모든 방식'],...(focusTopic==='pattern'?[['description','설명 → 이름']]:[]),['scenario','상황 → 이름'],['compare','헷갈리는 차이'],...(focusTopic==='pattern'?[['classification','생성·구조·행위 분류']]:[])]).map(([e,l])=>`<option value="${e}" ${focusExercise===e?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label class="field-label" for="focus-count">문제 수</label><select id="focus-count" class="select">${[5,10,20,999].map(n=>`<option value="${n}" ${focusCount===n?'selected':''}>${n===999?'선택 범위 전부':n+'문제'}</option>`).join('')}</select></div></div><div class="start-info"><span>${capacity}개 ${focusConcept==='all'?'개념':'문제'} · ${items.length}개 변형</span><span>덜 푼 문제 우선</span></div><button class="btn full start-btn" id="focus-start" ${items.length?'':'disabled'}><span>${items.length?'집중 연습 시작':'선택한 방식의 문제가 없어요'}</span><span>→</span></button><p class="footnote">${items.length?`${Math.min(capacity,focusCount)}문제 출제 · ${focusConcept==='all'?'한 세트에 개념당 한 문제':'선택한 개념의 서로 다른 유형'}`:'다른 연습 방식이나 개념을 선택해 주세요.'}</p><p class="muted">${seen===items.length&&items.length?'이 범위의 모든 문제를 확인했어요. 다음 학습은 복습 회독입니다.':`확인한 변형 ${seen} / ${items.length}개 · 기록은 이 브라우저에 저장됩니다.`}</p></section><aside class="side"><section class="card"><h2>이 범위의 오답</h2><div class="stat-number">${missed.length}<small>문제</small></div><p class="muted">지금 선택한 범위에서 틀린 문제만 다시 풀어보세요.</p><button class="btn secondary full" id="focus-wrong" ${missed.length?'':'disabled'}>이 범위 오답만 풀기</button></section><section class="card note-card"><h3>${focusTopic==='core'?'실기 출제 표기를 확인한 개념':focusTopic==='pattern'?'디자인 패턴 전체 범위':'아키텍처 보충 개념'}</h3><p>${focusTopic==='core'?'첨부 시나공 교재의 실기 출제 표기를 확인했습니다. 현재 확인 범위는 GoF·DB·SQL입니다. C·Java·Python은 ‘문제 풀기’에서 연습하세요. 해설에 연도·월과 PDF 페이지를 표시합니다.':focusTopic==='pattern'?'전체 GoF 패턴을 다룹니다. 실기 이력이 확인되는 개념은 해설에서 별도로 표시합니다.':'이 범위 전체를 실기 빈출로 확인한 것은 아닙니다. 핵심 실기 대비는 ‘실기 기출 핵심’을 먼저 풀어보세요.'}</p><p style="margin-top:12px">모든 문항은 개념을 바탕으로 재구성한 변형입니다. 공식 기출 원문이나 전 회차 빈도 통계는 아닙니다.</p></section></aside></div><section class="card focus-reference"><details><summary>학습 범위와 헷갈리는 차이 정리</summary><p class="muted">풀기 전 개념을 정리하거나, 문제를 푼 뒤 다시 확인해 보세요.</p><div class="concept-list">${concepts.map(c=>`<article><h3>${esc(c.name)} <small>${esc(c.english)} · ${esc(c.group)}</small></h3><p>${esc(c.summary)}</p><p class="muted">${esc(c.contrast)}</p></article>`).join('')}</div></details></section>`;
document.querySelectorAll('[data-focus-topic]').forEach(b=>b.onclick=()=>{focusTopic=b.dataset.focusTopic;focusGroup='all';focusConcept='all';focusExercise='all';renderFocus()});document.querySelectorAll('[data-focus-group]').forEach(b=>b.onclick=()=>{focusGroup=b.dataset.focusGroup;focusConcept='all';renderFocus()});$('#focus-concept').onchange=e=>{focusConcept=e.target.value;renderFocus()};$('#focus-exercise').onchange=e=>{focusExercise=e.target.value;renderFocus()};$('#focus-count').onchange=e=>{focusCount=Number(e.target.value);renderFocus()};$('#focus-start').onclick=()=>start(items,label,focusCount);$('#focus-wrong').onclick=()=>start(missed,label+' · 오답 복습',missed.length)}
function start(items,label,n){if(!items.length)return toast('출제할 문제가 없습니다.');session={origin:tab==='focus'?'focus':'practice',questions:selectQuestions(items,n,tab==='focus'&&focusConcept==='all'),label,index:0,results:[],checked:false,selection:null,started:Date.now(),done:false};tab=session.origin;nav();renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function current(){return session.questions[session.index]}
function renderQuestion(){const q=current();session.checked=false;const long=q.type==='sql'||q.type==='essay';
const hint=q.type==='essay'?'답안을 작성한 뒤 모범 답안과 비교해 보세요. 서술형은 자동 채점하지 않습니다.':q.type==='sql'?'문제에서 지정한 문법과 열 순서를 기준으로 채점합니다. 키워드 대소문자·공백·마지막 세미콜론은 구분하지 않습니다.':q.type==='output'?'출력값은 순서대로 작성하세요. 숫자의 부호와 소수점을 확인해 주세요.':'용어는 한글 또는 영어로 입력할 수 있어요. 여러 빈칸은 번호 순서대로 작성하세요.';
$('#main').innerHTML=`<div class="quiz-wrap"><div class="quiz-top"><button id="exit" class="btn text">← 학습 종료</button><span>${esc(session.label)}</span><span>${session.index+1} / ${session.questions.length}</span></div><div class="progress" role="progressbar" aria-label="학습 진행률" aria-valuemin="0" aria-valuemax="${session.questions.length}" aria-valuenow="${session.index}"><div style="width:${session.index/session.questions.length*100}%"></div></div><section class="card question-card"><div class="tags"><span>${esc(q.category)}</span><span>${typeName(q.type)}</span></div><div class="q-number">QUESTION ${String(session.index+1).padStart(2,'0')}</div><h2>${esc(q.prompt)}</h2><div id="answer-area"><label for="answer" class="field-label">나의 답안</label>${long?'<textarea id="answer" class="answer-input written-answer" rows="5" placeholder="답안을 직접 작성해 주세요" spellcheck="false"></textarea>':'<input id="answer" class="answer-input" placeholder="정답을 입력해 주세요" autocomplete="off">'}<p class="muted" style="margin-bottom:0">${hint}</p></div><div id="feedback" aria-live="polite"></div><div class="quiz-actions"><button id="reveal" class="btn text">모르겠어요 · 답안 보기</button><button id="check" class="btn">${q.type==='essay'?'모범 답안 확인':'정답 확인'} <span>→</span></button></div></section><p class="footnote">${long?'Ctrl 또는 ⌘ + Enter로 답안을 확인할 수 있어요.':'Enter 키로 정답을 확인할 수 있어요.'}</p></div>`;
$('#exit').onclick=()=>{if(session.results.length)finish(true);else{const origin=session.origin;session=null;setTab(origin)}};
$('#check').onclick=()=>check(false);$('#reveal').onclick=()=>check(true);$('#answer').onkeydown=e=>{if(e.key==='Enter'&&(!long||e.ctrlKey||e.metaKey)){e.preventDefault();check(false)}}}
function normalize(s){return String(s).normalize('NFKC').toLowerCase().replace(/[\s，,;:·()]/g,'')}
function answersMatch(input, expected){
 const numeric = v => {
  const s = String(v).normalize('NFKC').trim().replace(/−/g,'-');
  if (!/^[\d\s.,;\[\]+-]+$/.test(s)) return null;
  const parts = s.replace(/[\[\]]/g,'').split(/[\s,;]+/).filter(Boolean);
  if (!parts.length || parts.some(x => !/^[+-]?\d+(?:\.\d+)?$/.test(x))) return null;
  return parts.map(Number);
 };
 const a=numeric(input), b=numeric(expected);
 if(b) return !!a && a.length===b.length && a.every((v,i)=>v===b[i]);
 return normalize(input)===normalize(expected);
}
function sqlMatch(input,expected){
 const tokens = value => String(value).trim().replace(/;\s*$/,'').match(/'(?:''|[^'])*'|"(?:""|[^"])*"|[a-zA-Z_][a-zA-Z_0-9]*|\d+(?:\.\d+)?|>=|<=|<>|!=|[^\s]/g)?.map(t=>/^[\'"]/.test(t)?t:t.toUpperCase()).join('|')||'';
 return tokens(input)===tokens(expected);
}
function check(reveal){if(session.checked)return;const q=current(),input=$('#answer').value.trim();if(!reveal&&!input){toast('답안을 입력해 주세요.');$('#answer').focus();return}
const correct=q.type==='essay'?null:!reveal&&q.aliases.some(a=>q.type==='sql'?sqlMatch(input,a):answersMatch(input,a));session.checked=true;attempts[q.id]=(attempts[q.id]||0)+1;session.results.push({id:q.id,answer:input,correct});if(correct===true)wrong.delete(q.id);else if(correct===false)wrong.add(q.id);persist();$('#answer').disabled=true;showFeedback();$('#check').textContent=session.index===session.questions.length-1?'학습 결과 보기 →':'다음 문제 →';$('#check').onclick=()=>{if(session.index===session.questions.length-1)finish();else{session.index++;renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}};$('#reveal').style.visibility='hidden'}
function showFeedback(){const q=current(),r=session.results.at(-1),source=SOURCES.find(s=>s.id===`source-${q.source}`);$('#feedback').innerHTML=`<div class="feedback ${r.correct===false?'wrong':''}"><h3>${r.correct===null?'모범 답안과 비교해 보세요.':r.correct?'✓ 정답이에요!':'다음에는 기억할 수 있어요.'}</h3><p><strong>${q.type==='essay'?'모범 답안':'정답'} · ${esc(q.answer)}</strong></p>${r.answer&&r.correct!==true?`<p class="muted">나의 답 · ${esc(r.answer)}</p>`:''}<p>${esc(q.explanation)}</p>${q.type==='essay'?'<p class="muted">핵심 내용이 포함됐는지 확인해 보세요. 서술형은 정답률과 오답노트에 자동 반영하지 않습니다.</p>':''}${q.examEvidence?`<p class="muted"><strong>실기 기출 개념 변형 · ${esc(q.examEvidence.topic)}</strong><br>교재 실기 표기: ${q.examEvidence.dates.map(esc).join(', ')} · 시나공 PDF ${q.examEvidence.page}쪽<br>이력은 해당 개념의 출제 표기이며, 현재 문항 자체의 출제 이력은 아닙니다.</p>`:q.topic?'<p class="muted">보충 개념 변형 · 이 문항의 실기 출제 이력은 확인하지 않았습니다.</p>':''}<p class="source-ref">참고 · ${esc(source?.name||'첨부 학습자료')} · PDF ${q.page}쪽<br>핵심 개념을 바탕으로 구성한 실기 연습 문제</p></div>`}
function finish(partial=false){session.done=true;const total=session.results.length,graded=session.results.filter(r=>r.correct!==null).length,correct=session.results.filter(r=>r.correct===true).length;if(total){records.unshift({id:Date.now(),day:dateKey(),at:new Date().toISOString(),label:session.label,total,graded,correct,partial,seconds:Math.round((Date.now()-session.started)/1000)});records=records.slice(0,100);persist()}renderResult(partial)}
function renderResult(partial){const n=session.results.length,g=session.results.filter(r=>r.correct!==null).length,c=session.results.filter(r=>r.correct===true).length;$('#main').innerHTML=`<div class="quiz-wrap"><section class="card result"><div class="eyebrow">${partial?'STUDY SAVED':'WELL DONE'}</div><h1>${partial?'푼 문제까지 기록했어요.':'오늘도 한 걸음 더 가까이.'}</h1><p>${esc(session.label)} · ${n}문제 학습</p><div class="big-score">${g?Math.round(c/g*100):'답안 비교'}${g?'<span style="font-size:24px;letter-spacing:0">%</span>':''}</div><p>${g?`자동 채점 ${g}문제 중 ${c}문제 정답`:''}${n-g?`<br>서술형 ${n-g}문제 · 모범 답안 확인`:''}<br>${g-c?'틀린 문제는 오답노트에서 다시 만나요.':'다음 문제도 차근차근 풀어봐요.'}</p><div class="result-actions"><button class="btn" id="again">새 문제 풀기 →</button><button class="btn secondary" id="result-wrong">오답노트 보기</button></div></section><section class="card result-list" style="padding:10px 0">${session.results.map(r=>{const q=QUESTIONS.find(q=>q.id===r.id);return `<div class="result-row ${r.correct===false?'bad':''}"><b>${r.correct===null?'—':r.correct?'✓':'↺'}</b><div>${esc(q.prompt)}<br><span class="muted">${r.correct===null?'모범 답안':'정답'} · ${esc(q.answer)}</span></div></div>`}).join('')}</section></div>`;$('#again').textContent=session.origin==='focus'?'집중 연습 계속 →':'새 문제 풀기 →';$('#again').onclick=()=>{const origin=session.origin;session=null;setTab(origin)};$('#result-wrong').onclick=()=>{session=null;setTab('wrong')};window.scrollTo({top:0,behavior:'smooth'})}
function renderWrong(){const items=QUESTIONS.filter(q=>wrong.has(q.id));$('#main').innerHTML=`<h1 class="page-title">다시 보면, 내 것이 돼요.</h1><p class="page-sub">틀린 문제 ${items.length}개를 모았어요. 다시 풀어 정답을 맞히면 오답노트에서 빠집니다.</p>${items.length?`<div class="list-toolbar"><span class="muted">정답은 문제를 다시 풀 때 확인해 보세요.</span><button class="btn" id="review-all">오답 ${items.length}문제 다시 풀기 →</button></div>${items.map(q=>`<article class="card wrong-item"><div class="body"><div class="tags"><span>${esc(q.category)}</span><span>${typeName(q.type)}</span></div><h3>${esc(q.prompt)}</h3></div><button class="btn secondary" data-review="${q.id}">다시 풀기</button></article>`).join('')}`:`<section class="card empty"><div class="empty-symbol">✓</div><h2>아직 모아둔 오답이 없어요.</h2><p>문제를 풀며 헷갈렸던 개념을 이곳에 모아둘게요.<br>가볍게 첫 학습을 시작해 보세요.</p><button class="btn" id="empty-start">문제 풀기 →</button></section>`}`;if($('#review-all'))$('#review-all').onclick=()=>start(items,'오답 복습',items.length);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>start(items.filter(q=>q.id===b.dataset.review),'오답 복습',1));if($('#empty-start'))$('#empty-start').onclick=()=>setTab('practice')}
function renderHistory(){const total=records.reduce((a,r)=>a+r.total,0),correct=records.reduce((a,r)=>a+r.correct,0),graded=records.reduce((a,r)=>a+gradedCount(r),0);$('#main').innerHTML=`<h1 class="page-title">쌓이고 있는 나의 공부.</h1><p class="page-sub">${records.length}번의 학습 · 총 ${total}문제 · 정답률 ${graded?Math.round(correct/graded*100):0}% <span class="muted">(자동 채점 기준)</span></p>${records.length?records.map(r=>`<article class="card history-item"><div><strong>${esc(r.label)}</strong><small>${new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(r.at))} · ${r.total}문제${r.partial?' · 중간 종료':''}</small></div><div class="score">${gradedCount(r)?Math.round(r.correct/gradedCount(r)*100):'—'}${gradedCount(r)?'<small>%</small>':''}<small style="display:block;text-align:right">${gradedCount(r)?`${r.correct} / ${gradedCount(r)} 정답`:`서술형 ${r.total}문제`}</small></div></article>`).join(''):`<section class="card empty"><div class="empty-symbol">☷</div><h2>첫 번째 기록을 기다리고 있어요.</h2><p>학습을 마치면 날짜와 정답률을 기록해 드릴게요.</p><button class="btn" id="history-start">첫 학습 시작 →</button></section>`}<div class="bottom-note"><span class="dot"></span>이 브라우저의 기록입니다. 다른 기기와는 동기화되지 않습니다.</div>`;if($('#history-start'))$('#history-start').onclick=()=>setTab('practice')}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();setTab('practice')};$('#source-link').onclick=()=>{$('#source-list').innerHTML=SOURCES.map(s=>`<div class="source-entry">${esc(s.name)}<small>${s.pages}쪽 · 개념 참고 자료</small></div>`).join('');$('#sources').showModal()};$('#close-sources').onclick=()=>$('#sources').close();$('#sources').onclick=e=>{if(e.target===$('#sources')){const r=$('#sources').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#sources').close()}};render();
